select count(distinct client_msg_id)
from t_message
where from_user = #{fromUsername,jdbcType=VARCHAR}
  and to_user = #{toUsername,jdbcType=VARCHAR}
  and read_flag = 0
  and recalled = 0
  and id > #{afterId,jdbcType=BIGINT}

